begin;
select no_plan();
insert into auth.users(id,email) values(md5('subscription-refund-owner')::uuid,'subscription-refund@example.test');
select set_config('request.jwt.claim.sub',md5('subscription-refund-owner')::uuid::text,true);
select set_config('request.jwt.claims',jsonb_build_object('aal','aal2','amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',floor(extract(epoch from clock_timestamp())))))::text,true);
insert into public.platform_access_assignments(user_id,role_key,scope_kind) values(auth.uid(),'owner','platform');
select set_config('test.org',(select id::text from public.organizations where personal_owner_id=auth.uid()),true);
select set_config('test.order',public.reserve_sandbox_payment_order(current_setting('test.org')::uuid,gen_random_uuid(),0,platform_private.current_tariff_version('pro',clock_timestamp()),1000,'123','https://stage.qvesta.ru',now()+interval '1 day',now()+interval '31 days')->>'id',true);
select public.begin_sandbox_payment_send(current_setting('test.order')::uuid);
select public.record_sandbox_payment_result(current_setting('test.order')::uuid,md5('subscription-refund-payment')::uuid,'succeeded',true,true,null);
insert into public.billing_sandbox_application_scope values(current_setting('test.org')::uuid);
select set_config('test.receipt',public.request_platform_subscription_refund(current_setting('test.org')::uuid,current_setting('test.order')::uuid,md5('subscription-refund-command')::uuid)::text,true);
select is((current_setting('test.receipt')::jsonb->>'amount_minor'),'1000','future period fully refundable');
select is((current_setting('test.receipt')::jsonb->>'reserved'),'false','receipt does not reserve money');
select is(public.request_platform_subscription_refund(current_setting('test.org')::uuid,current_setting('test.order')::uuid,md5('subscription-refund-command')::uuid)::text,current_setting('test.receipt'),'retry preserves receipt and time');
select is(public.request_platform_subscription_refund(current_setting('test.org')::uuid,current_setting('test.order')::uuid,gen_random_uuid())->>'id',current_setting('test.receipt')::jsonb->>'id','new command cannot create second request for same order');
select throws_ok($$select public.request_platform_subscription_refund(gen_random_uuid(),current_setting('test.order')::uuid,md5('subscription-refund-command')::uuid)$$,'22023','subscription refund request conflict','cannot change organization on retry');
select is((select count(*)::integer from public.billing_sandbox_refunds where order_id=current_setting('test.order')::uuid),0,'no payment reserve created');
select ok((select relrowsecurity from pg_class where oid='public.subscription_refund_requests'::regclass),'RLS enabled');
set local role authenticated;
select throws_ok($$select * from public.subscription_refund_requests$$,'42501',null,'direct reads denied');
select throws_ok($$select public.request_platform_subscription_refund(null,null,null)$$,'42501',null,'RPC not enabled before integration');
set local role anon;
select throws_ok($$select * from public.subscription_refund_requests$$,'42501',null,'anonymous read denied');
set local role service_role;
select throws_ok($$select public.request_platform_subscription_refund(null,null,null)$$,'42501',null,'service RPC not prematurely enabled');
reset role;
-- A payment alone is not a license to change an arbitrary subscription.
select throws_ok($$select public.reserve_platform_subscription_refund((current_setting('test.receipt')::jsonb->>'id')::uuid)$$,'55000','subscription refund period not issued','unissued period cannot be reserved by termination flow');
select is((select count(*)::integer from public.subscription_refund_period_bindings),0,'failed binding leaves no row');
-- Trusted fixture: immutable confirmation for exactly the paid order.
update public.organization_subscriptions s set status='active',plan_version_id=o.plan_version_id,period_start=o.period_start,period_end=o.period_end from public.billing_sandbox_orders o where o.id=current_setting('test.order')::uuid and s.organization_id=o.organization_id;
insert into public.billing_period_confirmations(confirmation_id,organization_id,request,before_state,result)
select id,organization_id,jsonb_build_object('plan',plan_version_id,'start',period_start,'end',period_end),'{}',jsonb_build_object('revision',(select revision from public.organization_subscriptions where organization_id=public.billing_sandbox_orders.organization_id))
from public.billing_sandbox_orders where id=current_setting('test.order')::uuid;
savepoint changed_period;
update public.organization_subscriptions set period_end=period_end+interval '1 day' where organization_id=current_setting('test.org')::uuid;
select throws_ok($$select public.reserve_platform_subscription_refund((current_setting('test.receipt')::jsonb->>'id')::uuid)$$,'55000','subscription refund access review required','changed period rejected before reservation');
select is((select count(*)::integer from public.subscription_refund_reservations where request_id=(current_setting('test.receipt')::jsonb->>'id')::uuid),0,'no money reserved for changed period');
rollback to changed_period;
savepoint before_reserve;
select set_config('test.reserve',public.reserve_platform_subscription_refund((current_setting('test.receipt')::jsonb->>'id')::uuid)::text,true);
savepoint bad_context;
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select platform_private.claim_subscription_refund_dispatch(current_setting('test.reserve')::uuid)$$,'42501',null,'fresh MFA required');
rollback to bad_context;
savepoint changed_after_reserve;
update public.organization_subscriptions set period_end=period_end+interval '1 day' where organization_id=current_setting('test.org')::uuid;
select throws_ok($$select platform_private.claim_subscription_refund_dispatch(current_setting('test.reserve')::uuid)$$,'55000','subscription refund access review required','period rechecked at dispatch');
select is((select count(*)::integer from public.subscription_refund_dispatches),0,'failed authorization leaves no dispatch');
rollback to changed_after_reserve;
select is(platform_private.claim_subscription_refund_dispatch(current_setting('test.reserve')::uuid)->>'can_send','true','owner authorizes first send');
select is(platform_private.claim_subscription_refund_dispatch(current_setting('test.reserve')::uuid)->>'can_send','false','retry cannot authorize second send');
select is((select state from public.billing_sandbox_refunds where id=current_setting('test.reserve')::uuid),'sending','authorized refund marked sending');
select is((select count(*)::integer from public.subscription_refund_dispatches),1,'exactly one immutable authorization');
set local role authenticated;
select throws_ok($$select * from public.subscription_refund_dispatches$$,'42501',null,'dispatch journal private');
reset role;
set local role service_role;
select throws_ok($$select platform_private.claim_subscription_refund_dispatch(null)$$,'42501',null,'sender remains closed until gateway integration');
reset role;
select is(platform_private.prepare_subscription_refund_recovery(current_setting('test.reserve')::uuid)->>'action','retry_same_request','lost response uses recovery');
select is(platform_private.prepare_subscription_refund_recovery(current_setting('test.reserve')::uuid)->>'idempotency_key',current_setting('test.reserve'),'recovery preserves original idempotency key');
select is(platform_private.prepare_subscription_refund_recovery(current_setting('test.reserve')::uuid)->>'amount_minor','1000','recovery preserves original amount');
create function pg_temp.result(status text,amount bigint default 1000,payment uuid default md5('subscription-refund-payment')::uuid,provider uuid default md5('refund-result-provider')::uuid) returns jsonb language sql as $$
 select platform_private.record_subscription_refund_result(current_setting('test.reserve')::uuid,'123',payment,provider,status,amount,'RUB'); $$;
select throws_ok($$select pg_temp.result('succeeded',999)$$,'22023','invalid subscription refund result','wrong amount rejected');
select throws_ok($$select pg_temp.result('succeeded',1000,gen_random_uuid())$$,'22023','invalid subscription refund result','foreign payment rejected');
select throws_ok($$select pg_temp.result('unknown')$$,'22023','invalid subscription refund result','unknown status is not success');
select is((select provider_refund_id from public.billing_sandbox_refunds where id=current_setting('test.reserve')::uuid),null::uuid,'invalid results do not bind identity');
savepoint rejected_result;
select set_config('test.subscription_before', (select to_jsonb(s)::text from public.organization_subscriptions s where organization_id=current_setting('test.org')::uuid),true);
select is(public.subscription_refund_from_gateway(md5('subscription-refund-owner')::uuid,floor(extract(epoch from clock_timestamp()))::bigint,floor(extract(epoch from clock_timestamp()))::bigint+300,'reject',current_setting('test.reserve')::uuid)->>'state','rejected','gateway rejection releases reservation');
select is(platform_private.reject_subscription_refund(current_setting('test.reserve')::uuid)->>'state','rejected','rejection replay stable');
select is((select to_jsonb(s)::text from public.organization_subscriptions s where organization_id=current_setting('test.org')::uuid),current_setting('test.subscription_before'),'rejection preserves subscription');
select is((select count(*)::integer from public.subscription_refund_applications where refund_id=current_setting('test.reserve')::uuid),0,'rejection does not apply access');
set local role authenticated;
select throws_ok($$select platform_private.reject_subscription_refund(null)$$,'42501',null,'client cannot reject refund');
reset role;
rollback to rejected_result;
select is(pg_temp.result('pending')->>'access_state','not_applied','first pending binds without ending access');
select throws_ok($$select platform_private.reject_subscription_refund(current_setting('test.reserve')::uuid)$$,'55000','subscription refund rejection conflict','known provider refund cannot be rejected');
select is((select provider_refund_id from public.billing_sandbox_refunds where id=current_setting('test.reserve')::uuid),md5('refund-result-provider')::uuid,'provider identity saved');
select is(platform_private.prepare_subscription_refund_recovery(current_setting('test.reserve')::uuid)->>'action','read_provider','known provider identity uses read only');
select throws_ok($$select pg_temp.result('succeeded',1000,md5('subscription-refund-payment')::uuid,gen_random_uuid())$$,'22023','refund identity conflict','provider identity cannot change');
select is(pg_temp.result('succeeded')->>'access_state','applied','verified success applies access');
select is(pg_temp.result('succeeded')->>'access_state','applied','success replay does not repeat operation');
select is(pg_temp.result('pending')#>>'{refund,state}','succeeded','late pending cannot regress success');
select is(pg_temp.result('canceled')#>>'{refund,state}','review','contradictory terminal result requires review');
select is((select count(*)::integer from public.subscription_refund_applications where refund_id=current_setting('test.reserve')::uuid),1,'single access application');
select set_config('test.claims',current_setting('request.jwt.claims'),true);
set local role service_role;
select is(public.subscription_refund_from_gateway(md5('subscription-refund-owner')::uuid,floor(extract(epoch from clock_timestamp()))::bigint,floor(extract(epoch from clock_timestamp()))::bigint+300,'read',current_setting('test.reserve')::uuid)#>>'{refund,id}',current_setting('test.reserve'),'gateway reads authorized subscription refund');
select is(current_setting('request.jwt.claims'),current_setting('test.claims'),'gateway restores caller claims');
select throws_ok($$select public.subscription_refund_from_gateway(md5('subscription-refund-owner')::uuid,0,9999999999,'read',current_setting('test.reserve')::uuid)$$,'42501','invalid refund gateway context','stale MFA denied by gateway');
reset role;
set local role authenticated;
select throws_ok($$select public.subscription_refund_from_gateway(null,null,null,'read',null)$$,'42501',null,'client cannot forge gateway identity');
reset role;
select is(public.read_platform_order_refunds(current_setting('test.org')::uuid,current_setting('test.order')::uuid)#>>'{items,0,refund_kind}','subscription','history identifies subscription refund');
select is(public.read_platform_order_refunds(current_setting('test.org')::uuid,current_setting('test.order')::uuid)#>>'{items,0,access_state}','applied_review_required','history retains applied access when money requires review');
select is(public.read_platform_order_refunds(current_setting('test.org')::uuid,current_setting('test.order')::uuid)#>>'{items,0,can_resume}','false','subscription refund never resumes in legacy flow');
select * from finish();rollback;